<?php require_once __DIR__ . '/../includes/auth.php'; require_admin(); require_once __DIR__ . '/../config/database.php'; require_once __DIR__ . '/../includes/functions.php'; $id=(int)$_POST['id']; $s=$conn->prepare('SELECT file_name FROM employee_documents WHERE id=?'); $s->bind_param('i',$id); $s->execute(); $doc=$s->get_result()->fetch_assoc(); if($doc && file_exists(__DIR__.'/../assets/uploads/'.$doc['file_name'])) unlink(__DIR__.'/../assets/uploads/'.$doc['file_name']); $d=$conn->prepare('DELETE FROM employee_documents WHERE id=?'); $d->bind_param('i',$id); $d->execute(); set_flash('success','Document deleted.'); redirect('index.php'); ?>
